111	 * A non-production grade rust implementation to prove out loading multiple different versionActions in various setups
112	 */
113	interface CargoToml {
114	  workspace?: { members: string[] };
115	  package: { name: string; version: string };
116	  dependencies?: Record<
117	    string,
118	    string | { version: string; features?: string[]; optional?: boolean }
119	  >;
120	  'dev-dependencies'?: Record<
121	    string,
122	    string | { version: string; features: string[] }
123	  >;
124	
