128	export class ExampleRustVersionActions extends VersionActions {
129	  validManifestFilenames = ['Cargo.toml'];
130	
131	  private parseCargoToml(cargoString: string): CargoToml {
132	    return TOML.parse(cargoString, {
133	      x: { comment: true },
134	    }) as CargoToml;
135	  }
136	
137	  static stringifyCargoToml(cargoToml: CargoToml): string {
138	    const tomlString = TOML.stringify(cargoToml, {
139	      newlineAround: 'section',
140	    });
141	    return Array.isArray(tomlString) ? tomlString.join('\n') : tomlString;
142	  }
143	
144	  static modifyCargoTable(
145	    toml: CargoToml,
146	    section: string,
147	    key: string,
148	    value: string | object | Array<any> | (() => any)
149	  ) {
150	    toml[section] ??= TOML.Section({});
151	    toml[section][key] =
152	      typeof value === 'object' && !Array.isArray(value)
153	        ? TOML.inline(value as any)
154	        : typeof value === 'function'
155	          ? value()
156	          : value;
157	  }
158	
159	  async readCurrentVersionFromSourceManifest(tree: Tree): Promise<{
160	    currentVersion: string;
161	    manifestPath: string;
162	  }> {
163	    const cargoTomlPath = join(this.projectGraphNode.data.root, 'Cargo.toml');
164	    const cargoTomlString = tree.read(cargoTomlPath, 'utf-8')!.toString();
165	    const cargoToml = this.parseCargoToml(cargoTomlString);
166	    const currentVersion = cargoToml.package?.version || '0.0.0';
167	    return {
168	      currentVersion,
169	      manifestPath: cargoTomlPath,
170	    };
171	  }
172	
173	  async readCurrentVersionFromRegistry(
174	    tree: Tree,
175	    _currentVersionResolverMetadata: NxReleaseVersionConfiguration['currentVersionResolverMetadata']
176	  ): Promise<{
177	    currentVersion: string;
178	    logText: string;
179	  }> {
180	    // Real registry resolver not needed for this test example
181	    return {
182	      currentVersion: (await this.readCurrentVersionFromSourceManifest(tree))
183	        .currentVersion,
184	      logText: 'https://example.com/fake-registry',
185	    };
186	  }
187	
188	  async updateProjectVersion(tree: Tree, newVersion: string) {
189	    const logMessages: string[] = [];
190	    for (const manifestToUpdate of this.manifestsToUpdate) {
191	      const cargoTomlString = tree
192	        .read(manifestToUpdate.manifestPath, 'utf-8')!
193	        .toString();
194	      const cargoToml = this.parseCargoToml(cargoTomlString);
195	      ExampleRustVersionActions.modifyCargoTable(
196	        cargoToml,
197	        'package',
198	        'version',
199	        newVersion
200	      );
201	      const updatedCargoTomlString =
202	        ExampleRustVersionActions.stringifyCargoToml(cargoToml);
203	      tree.write(manifestToUpdate.manifestPath, updatedCargoTomlString);
204	      logMessages.push(
205	        `✍️  New version ${newVersion} written to manifest: ${manifestToUpdate.manifestPath}`
206	      );
207	    }
208	    return logMessages;
209	  }
210	
211	  async readCurrentVersionOfDependency(
212	    tree: Tree,
213	    _projectGraph: ProjectGraph,
214	    dependencyProjectName: string
215	  ): Promise<{ currentVersion: string; dependencyCollection: string }> {
216	    const cargoTomlPath = join(this.projectGraphNode.data.root, 'Cargo.toml');
217	    const cargoTomlString = tree.read(cargoTomlPath, 'utf-8')!.toString();
218	    const cargoToml = this.parseCargoToml(cargoTomlString);
219	    const dependencyVersion = cargoToml.dependencies?.[dependencyProjectName];
220	    if (typeof dependencyVersion === 'string') {
221	      return {
222	        currentVersion: dependencyVersion,
223	        dependencyCollection: 'dependencies',
224	      };
225	    }
226	    return {
227	      currentVersion: dependencyVersion?.version || '0.0.0',
228	      dependencyCollection: 'dependencies',
229	    };
230	  }
231	
232	  // NOTE: Does not take the preserveLocalDependencyProtocols setting into account yet
233	  async updateProjectDependencies(
234	    tree: Tree,
235	    _projectGraph: ProjectGraph,
236	    dependenciesToUpdate: Record<string, string>
237	  ): Promise<string[]> {
238	    const numDependenciesToUpdate = Object.keys(dependenciesToUpdate).length;
239	    const depText =
240	      numDependenciesToUpdate === 1 ? 'dependency' : 'dependencies';
241	    if (numDependenciesToUpdate === 0) {
242	      return [];
243	    }
244	
245	    const logMessages: string[] = [];
246	    for (const manifestToUpdate of this.manifestsToUpdate) {
247	      const cargoTomlString = tree
248	        .read(manifestToUpdate.manifestPath, 'utf-8')!
249	        .toString();
250	      const cargoToml = this.parseCargoToml(cargoTomlString);
251	
252	      for (const [dep, version] of Object.entries(dependenciesToUpdate)) {
253	        ExampleRustVersionActions.modifyCargoTable(
254	          cargoToml,
255	          'dependencies',
256	          dep,
257	          version
258	        );
259	      }
260	
261	      const updatedCargoTomlString =
262	        ExampleRustVersionActions.stringifyCargoToml(cargoToml);
263	      tree.write(manifestToUpdate.manifestPath, updatedCargoTomlString);
264	
265	      logMessages.push(
266	        `✍️  Updated ${numDependenciesToUpdate} ${depText} in manifest: ${manifestToUpdate.manifestPath}`
267	      );
268	    }
269	    return logMessages;
270	  }
271	}
